constraints:
1<=N<=10^{5}

expected time complexity: O(Nlog_{10}N)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def SumSquare(self, n):
		summ = 0
		while n != 0:
			dg = n % 10
			summ += dg * dg
			n //= 10
		return summ

	def isHappy(self, n):
		st = set()
		st.add(n)
		while True:
			if n == 1:
				return 1
			n = self.SumSquare(n)
			if n in st:
				return 0
			st.add(n)
		return 0

	def nextHappy(self, N):
		for i in range(N + 1, N + 100):
			if self.isHappy(i):
				return i
		return -1
